     9→use std::hint::black_box;
    10→
    11→/// Benchmarks different implementations of the root calculation.
    12→pub fn trie_root_benchmark(c: &mut Criterion) {
    13→    let mut group = c.benchmark_group("Receipts root calculation");
    14→
    15→    for size in [10, 100, 1_000] {
    16→        let group_name =
    17→            |description: &str| format!("receipts root | size: {size} | {description}");
    18→
    19→        let receipts = &generate_test_data(size)[..];
    20→        assert_eq!(trie_hash_ordered_trie_root(receipts), hash_builder_root(receipts));
    21→
    22→        group.bench_function(group_name("triehash::ordered_trie_root"), |b| {
    23→            b.iter(|| trie_hash_ordered_trie_root(black_box(receipts)));
    24→        });
    25→
    26→        group.bench_function(group_name("HashBuilder"), |b| {
    27→            b.iter(|| hash_builder_root(black_box(receipts)));
    28→        });
    29→    }
    30→}
    31→
    32→fn generate_test_data(size: usize) -> Vec<ReceiptWithBloom<Receipt>> {
    33→    prop::collection::vec(arb::<ReceiptWithBloom<Receipt>>(), size)
    34→        .new_tree(&mut TestRunner::deterministic())
    35→        .unwrap()
    36→        .current()
    37→}
    38→
    39→criterion_group! {
    40→    name = benches;
    41→    config = Criterion::default();
    42→    targets = trie_root_benchmark
    43→}
    44→criterion_main!(benches);
    45→
    46→mod implementations {
    47→    use super::*;
    48→    use alloy_eips::eip2718::Encodable2718;
    49→    use alloy_rlp::Encodable;
    50→    use alloy_trie::root::adjust_index_for_rlp;
    51→    use reth_trie_common::{HashBuilder, Nibbles};
    52→
    53→    pub fn trie_hash_ordered_trie_root(receipts: &[ReceiptWithBloom<Receipt>]) -> B256 {
    54→        triehash::ordered_trie_root::<KeccakHasher, _>(
    55→            receipts.iter().map(|receipt_with_bloom| receipt_with_bloom.encoded_2718()),
    56→        )
    57→    }
    58→
    59→    pub fn hash_builder_root(receipts: &[ReceiptWithBloom<Receipt>]) -> B256 {
    60→        let mut index_buffer = Vec::new();
    61→        let mut value_buffer = Vec::new();
    62→
    63→        let mut hb = HashBuilder::default();
    64→        let receipts_len = receipts.len();
    65→        for i in 0..receipts_len {
    66→            let index = adjust_index_for_rlp(i, receipts_len);
    67→
    68→            index_buffer.clear();
    69→            index.encode(&mut index_buffer);
    70→
    71→            value_buffer.clear();
    72→            receipts[index].encode_2718(&mut value_buffer);
    73→
    74→            hb.add_leaf(Nibbles::unpack(&index_buffer), &value_buffer);
    75→        }
    76→
    77→        hb.root()
    78→    }
    79→}
